'use client';

import React, { useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import Link from 'next/link';
import Image from 'next/image';
import { 
  BookOpen, ArrowLeft, MessageSquare, Sparkles, ShieldCheck, CheckCircle2, Clock, Play, Home, Calendar, Bot, Fingerprint, Award
} from 'lucide-react';
import AITeacherDrawer from '@/components/AITeacherDrawer';
import { getLessonsByStudent, getSubjectsByStudent } from '../../../data/microcurriculum';

export default function StudentDashboard() {
  const params = useParams();
  const router = useRouter();
  const rawStudent = (params.student as string)?.toLowerCase();
  const isAvril = rawStudent === 'avril';
  const studentName = isAvril ? 'Avril' : 'Gael';

  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [selectedSubject, setSelectedSubject] = useState(isAvril ? 'Ciencias' : 'Exploración');

  const [lessons, setLessons] = useState(() => getLessonsByStudent(rawStudent));
  const subjectsInfo = getSubjectsByStudent(rawStudent);

  const toggleComplete = (id: string) => {
    setLessons((prev) =>
      prev.map((l) => (l.id === id ? { ...l, completed: !l.completed } : l))
    );
  };

  const validateProgress = () => {
    setLessons((prev) =>
      prev.map((l) => (l.completed ? { ...l, parentApproved: true } : l))
    );
  };

  const approvedCount = lessons.filter((l) => l.parentApproved).length;
  const currentProgress = lessons.length > 0 ? Math.round((approvedCount / lessons.length) * 100) : 0;
  const pendingApproval = lessons.some((l) => l.completed && !l.parentApproved);
  const hasCompletedLessons = lessons.some((l) => l.completed);

  const studentConfig = isAvril ? {
    name: 'Avril',
    grade: '8vo de Básica',
    badge: '🐶 Mundo Snoopy',
    methodology: 'Montessori / Charlotte Mason',
    colorAccent: 'border-indigo-500 bg-indigo-500/10 text-indigo-400',
    btnBg: 'bg-indigo-600 hover:bg-indigo-500',
    teacher: { name: 'Dra. Elena (IA Ciencias)', avatar: '' },
    subjects: ['Ciencias', 'Investigación', 'Matemáticas', 'Literatura'],
    accentGradient: 'from-indigo-600 via-blue-600 to-sky-500'
  } : {
    name: 'Gael',
    grade: '4to de Básica',
    badge: '🍄 Mundo Mario Bros',
    methodology: 'Misiones & Gamificación',
    colorAccent: 'border-amber-500 bg-amber-500/10 text-amber-400',
    btnBg: 'bg-amber-600 hover:bg-amber-500',
    teacher: { name: 'Prof. Mario (IA Exploración)', avatar: '' },
    subjects: ['Exploración', 'Lectoescritura', 'Matemáticas', 'Retos'],
    accentGradient: 'from-amber-400 via-orange-400 to-amber-500'
  };

  const dailyClass = {
    theme: isAvril ? 'El método científico' : 'La aventura de las fracciones',
    description: isAvril 
      ? 'Aprenderemos a formular hipótesis haciendo experimentos sencillos.' 
      : 'Usa tus piezas para dividir un grupo en partes iguales.'
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col md:flex-row">
      <aside className="w-full md:w-72 bg-slate-900 border-r border-slate-800 p-6 flex flex-col justify-between shrink-0">
        <div className="space-y-6">
          <button onClick={() => router.push('/')} className="flex items-center gap-2 text-sm font-bold text-slate-400 hover:text-white transition-colors">
            <ArrowLeft className="w-5 h-5" /> Volver al inicio
          </button>
          <div className="p-5 rounded-2xl bg-slate-800/80 border border-slate-700/60 flex items-center gap-4">
            <div className="w-14 h-14 rounded-xl bg-slate-700 flex items-center justify-center font-bold text-white text-xl">
              {studentName.charAt(0)}
            </div>
            <div>
              <h2 className="text-lg font-bold text-white">{studentName}</h2>
              <p className="text-xs text-slate-400">{studentConfig.grade}</p>
              <span className={`inline-block text-[10px] px-2 py-0.5 rounded font-semibold ${studentConfig.colorAccent}`}>
                {studentConfig.badge}
              </span>
            </div>
          </div>
          <nav className="space-y-2">
            <div className="px-3 py-2 text-xs font-bold text-slate-500 uppercase tracking-wider">Materias</div>
            {studentConfig.subjects.map((sub) => (
              <button
                key={sub}
                onClick={() => setSelectedSubject(sub)}
                className={`w-full text-left px-4 py-3 rounded-xl text-sm font-medium flex items-center justify-between ${selectedSubject === sub ? 'bg-indigo-600/20 text-indigo-300 border border-indigo-500/30' : 'text-slate-400 hover:bg-slate-800'}`}
              >
                <span>{sub}</span>
                {selectedSubject === sub && <Sparkles className="w-4 h-4 text-indigo-400" />}
              </button>
            ))}
          </nav>
        </div>
        <div className="mt-6 p-4 rounded-xl bg-slate-800/40 border border-slate-800 text-sm text-slate-400">
          <span className="font-bold text-slate-300 block mb-1">Método</span>
          <p>{studentConfig.methodology}</p>
        </div>
      </aside>

      <main className="flex-1 p-6 md:p-10 lg:p-12 space-y-8 overflow-y-auto">
        <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-slate-800 pb-6">
          <div>
            <h1 className="text-3xl md:text-4xl font-black text-white">Espacio de Aprendizaje - {selectedSubject}</h1>
            <p className="text-sm text-slate-400 mt-1">Wisdom School • Curriculum Internacional</p>
          </div>
          <button onClick={() => setIsDrawerOpen(true)} className={`px-6 py-3 rounded-xl font-bold text-sm text-white shadow-lg flex items-center gap-2 ${studentConfig.btnBg}`}>
            <MessageSquare className="w-5 h-5" />
            <span>Consultar al Tutor IA ({studentConfig.teacher.name})</span>
          </button>
        </header>

        {/* Progreso + Validador */}
        <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
          <div className="md:col-span-4 bg-slate-900 rounded-2xl p-6 border border-slate-800 flex flex-col items-center justify-center text-center">
            <span className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-3">Progreso Aprobado</span>
            <div className="relative w-28 h-28 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90" viewBox="0 0 36 36">
                <path className="text-slate-800" strokeWidth="3.5" stroke="currentColor" fill="none" d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" />
                <path className="text-emerald-500 transition-all duration-500" strokeDasharray={`${currentProgress}, 100`} strokeWidth="3.5" strokeLinecap="round" stroke="currentColor" fill="none" d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" />
              </svg>
              <span className="absolute text-2xl font-black text-white">{currentProgress}%</span>
            </div>
            <span className="text-xs font-bold text-slate-400 mt-2">{approvedCount} de {lessons.length} validadas</span>
          </div>
          <div className="md:col-span-8 bg-slate-900 rounded-2xl p-6 border border-slate-800 flex flex-col justify-center gap-4">
            <div className="flex items-center gap-2 text-sm font-bold text-amber-400 uppercase">
              <BookOpen className="w-5 h-5" /> Lección del Día
            </div>
            <h3 className="text-xl font-bold text-white">{dailyClass.theme}</h3>
            <p className="text-sm text-slate-300 leading-relaxed">{dailyClass.description}</p>
            <div className="pt-4 border-t border-slate-800 flex items-center gap-4">
              <button onClick={() => setIsDrawerOpen(true)} className="px-5 py-2.5 rounded-lg bg-indigo-600/20 hover:bg-indigo-600/30 text-indigo-300 border border-indigo-500/30 text-sm font-semibold flex items-center gap-2">
                <Sparkles className="w-4 h-4" /> Pedir Pista Socrática al Profesor
              </button>
              {pendingApproval && (
                <div className="p-2.5 rounded-xl bg-amber-500/10 border border-amber-500/30 text-xs font-bold text-amber-400 flex items-center gap-2">
                  <Fingerprint className="w-4 h-4" /> Pendiente de validación
                </div>
              )}
              {!pendingApproval && currentProgress > 0 && (
                <div className="p-2.5 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-xs font-bold text-emerald-400 flex items-center gap-2">
                  <ShieldCheck className="w-4 h-4" /> Aprobado por Padres
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Validador Parental */}
        <div className="p-6 rounded-2xl bg-slate-900 border border-slate-800 flex items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 rounded-2xl bg-emerald-600/20 flex items-center justify-center">
              <ShieldCheck className="w-8 h-8 text-emerald-400" />
            </div>
            <div>
              <h3 className="text-lg font-black text-white">Validador Parental</h3>
              <p className="text-sm text-slate-400">Los padres validan el avance al hacer clic en "Aprobar"</p>
            </div>
          </div>
          <button
            onClick={validateProgress}
            disabled={!hasCompletedLessons}
            className={`px-8 py-4 rounded-2xl font-black text-sm transition-all flex items-center gap-2 ${
              hasCompletedLessons
                ? 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-lg shadow-emerald-200'
                : 'bg-slate-200 text-slate-400 cursor-not-allowed'
            }`}
          >
            <ShieldCheck className="w-6 h-6" />
            Aprobar Avance
          </button>
        </div>

        {/* Lista de Lecciones */}
        <div className="space-y-4">
          {lessons.map((lesson) => {
            const sub = subjectsInfo.find((s) => s.id === lesson.subjectId);
            return (
              <div 
                key={lesson.id} 
                className={`p-6 rounded-2xl border transition-all flex flex-col sm:flex-row sm:items-center justify-between gap-4 ${
                  lesson.parentApproved ? 'border-emerald-500/30 bg-emerald-500/5' : 'border-slate-800 bg-slate-900'
                }`}
              >
                <div className="flex items-center gap-4">
                  <div className={`w-14 h-14 rounded-xl flex items-center justify-center font-bold text-white shadow-sm ${lesson.subjectColor}`}>
                    <BookOpen className="w-6 h-6" />
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <h4 className="font-bold text-white text-base">{lesson.subjectName}</h4>
                      <span className="text-xs font-semibold text-slate-400 flex items-center gap-1">
                        <Clock className="w-3 h-3" /> {lesson.time}
                      </span>
                    </div>
                    <p className="text-sm text-slate-400 font-medium mt-0.5">
                      {lesson.description} • <span className="text-slate-500">Prof. {lesson.tutorName}</span>
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-3 self-end sm:self-center">
                  <button 
                    onClick={() => toggleComplete(lesson.id)}
                    className={`px-6 py-3 rounded-xl text-sm font-bold transition-all flex items-center gap-2 ${
                      lesson.parentApproved 
                        ? 'bg-emerald-600 text-white shadow-sm' 
                        : 'bg-slate-800 text-slate-300 hover:bg-slate-700'
                    }`}
                  >
                    <CheckCircle2 className="w-5 h-5" />
                    {lesson.parentApproved ? 'Validado' : 'Marcar lista'}
                  </button>
                  <button className="px-6 py-3 rounded-xl text-sm font-bold bg-indigo-600 text-white hover:bg-indigo-700 transition-all flex items-center gap-2 shadow-sm">
                    <Play className="w-4 h-4 fill-current" />
                    Entrar
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      </main>

      <AITeacherDrawer
        isOpen={isDrawerOpen}
        onClose={() => setIsDrawerOpen(false)}
        student={isAvril ? 'Avril' : 'Gael'}
        asignatura={selectedSubject}
        teacher={studentConfig.teacher}
        dailyClass={{ theme: dailyClass.theme }}
      />
    </div>
  );
}