// Helpers útiles para consultar datos cómodamente en los componentes
export function getStudentProfile(studentId: string): StudentProfile | undefined {
  return studentProfiles[studentId];
}

export function getSubjectsByStudent(studentId: string): (Subject & { tutor: VirtualTutor })[] {
  const filteredSubjects = subjects.filter(sub => sub.id.startsWith(studentId));
  return filteredSubjects.map(sub => ({
    ...sub,
    tutor: virtualTutors[sub.tutorId]
  }));
}

export function getLessonsByStudent(studentId: string): (Lesson & { subjectName: string; subjectColor: string; tutorName: string; tutorId: string; tutorColor: string })[] {
  const studentLessons = initialLessons.filter(lesson => lesson.subjectId.startsWith(studentId));
  return studentLessons.map(lesson => {
    const sub = subjects.find(s => s.id === lesson.subjectId)!;
    const tut = virtualTutors[sub.tutorId];
    return {
      ...lesson,
      subjectName: sub.name,
      subjectColor: sub.color,
      tutorName: tut.name,
      tutorId: tut.id,
      tutorColor: tut.avatarColor
    };
  }).sort((a, b) => a.order - b.order);
}

